}

// GenerateAuthURL generates an OAuth2 authorization URL for the user to authenticate.
// The redirectPath parameter allows customization of where the user should be redirected after auth.
func GenerateAuthURL(redirectPath string, session *http.Cookie, w http.ResponseWriter, r *http.Request) (string, error) {
	// Generate a cryptographically random state value
	state, err := generateRandomState()
	if err != nil {
		return "", err
	}

	// Validate and sanitize the redirectPath to prevent open redirect attacks
	safeRedirectURL, err := validateAndSanitizeRedirectURL(redirectPath)
	if err != nil {
		return "", err
	}

	// Create a copy of the OAuth config with the custom redirect URL
	config := *OAuthConfig
	config.RedirectURL = safeRedirectURL

	// Generate the authorization URL
	authURL := config.AuthCodeURL(state)

	// Set the state in a cookie for later validation
	http.SetCookie(w, &http.Cookie{
		Name:     "oauth_state",
		Value:    state,
		HttpOnly: true,
		Secure:   true,
		SameSite: http.SameSiteLaxMode,
		Path:     "/",
	})

	return authURL, nil
}

// generateRandomState generates a cryptographically random state string for OAuth CSRF protection.
func generateRandomState() (string, error) {
	b := make([]byte, 32)
	_, err := rand.Read(b)
	if err != nil {
		return "", errors.New("failed to generate random state")
	}
	return base64.URLEncoding.EncodeToString(b), nil
}

// validateAndSanitizeRedirectURL validates that the redirect URL is safe and belongs to the allowed domain.
func validateAndSanitizeRedirectURL(redirectPath string) (string, error) {
	if redirectPath == "" {
		return "", errors.New("redirect path cannot be empty")
	}

	// Parse the provided redirect URL
	parsedURL, err := url.Parse(redirectPath)
	if err != nil {
		return "", errors.New("invalid redirect URL")
	}

	// Ensure the URL has a scheme and host
	if parsedURL.Scheme == "" || parsedURL.Host == "" {
		return "", errors.New("redirect URL must be absolute")
	}

	// Only allow HTTPS to prevent MITM attacks
	if parsedURL.Scheme != "https" {
		return "", errors.New("redirect URL must use HTTPS")
	}

	// Validate that the host matches the allowed domain
	allowedHost := "yourapp.com"
	if !strings.HasSuffix(parsedURL.Hostname(), allowedHost) {
		return "", errors.New("redirect URL must be to an allowed domain")
	}

	// Prevent path traversal or other malicious path manipulation
	// Ensure the path doesn't contain suspicious patterns
	if strings.Contains(parsedURL.Path, "..") {
		return "", errors.New("redirect URL contains invalid path")
	}

	// Reconstruct the URL to ensure it's properly formatted and sanitized
	safeURL := url.URL{
		Scheme:   parsedURL.Scheme,
		Host:     parsedURL.Host,
		Path:     parsedURL.Path,
		RawQuery: parsedURL.RawQuery,
	}

	return safeURL.String(), nil
}

