// The redirectPath parameter allows customization of where the user should be redirected after auth.
func GenerateAuthURL(redirectPath string, session *http.Cookie, w http.ResponseWriter, r *http.Request) (string, error) {
	// Validate redirectPath to prevent open redirect attacks
	if redirectPath == "" {
		redirectPath = "/"
	}

	// Ensure the redirect path is a local path (starts with /)
	if !strings.HasPrefix(redirectPath, "/") {
		return "", fmt.Errorf("invalid redirect path: must start with /")
	}

	// Create a state parameter that includes the redirect path
	// The state will be returned by the OAuth provider after authentication
	stateData := map[string]string{
		"redirect": redirectPath,
	}

	// If a session cookie is provided, include session info in state
	if session != nil {
		stateData["session_id"] = session.Value
	}

	// Marshal state data to JSON
	stateJSON, err := json.Marshal(stateData)
	if err != nil {
		return "", fmt.Errorf("failed to marshal state data: %w", err)
	}

	// Encode state as base64 to make it URL-safe
	state := base64.URLEncoding.EncodeToString(stateJSON)

	// Generate the authorization URL using oauth2 package
	authURL := OAuthConfig.AuthCodeURL(state, oauth2.AccessTypeOffline)

	// Parse the generated URL to add additional parameters if needed
	parsedURL, err := url.Parse(authURL)
	if err != nil {
		return "", fmt.Errorf("failed to parse auth URL: %w", err)
	}

	// Optionally set the session cookie for CSRF protection
	if session != nil {
		http.SetCookie(w, session)
	}

	return parsedURL.String(), nil
}

func main() {
	// Example usage
	http.HandleFunc("/login", func(w http.ResponseWriter, r *http.Request) {
		// Get redirect path from query parameter or use default
